import json
import re
import sys

def strict_object(pairs):
    result = {}
    for key, value in pairs:
        if key in result:
            raise ValueError("Duplicate JSON key: " + key)
        result[key] = value
    return result

organization = sys.argv[1].strip()
definitionName = sys.argv[2].strip()
try: definitionVersion = int(sys.argv[3])
except Exception: definitionVersion = 0
definitionDescription = sys.argv[4]
platform = sys.argv[5].strip()
preferredVersion = sys.argv[7].strip().lower() == "true"
waitRequested = sys.argv[10].strip().lower() == "true"
try: timeoutSeconds = int(sys.argv[11])
except Exception: timeoutSeconds = 0
errors = []
configs, parsedTags, parsedRollout = [], [], None
try: configs = json.loads(sys.argv[6], object_pairs_hook=strict_object)
except Exception as exc: errors.append("Blueprint Configuration is invalid JSON: " + str(exc))
try: parsedTags = json.loads(sys.argv[9], object_pairs_hook=strict_object)
except Exception as exc: errors.append("Tags is invalid JSON: " + str(exc))
if sys.argv[8].strip():
    try: parsedRollout = json.loads(sys.argv[8], object_pairs_hook=strict_object)
    except Exception as exc: errors.append("Preferred Version Rollout Strategy is invalid JSON: " + str(exc))
if not organization: errors.append("Workload Organization must not be blank.")
if not re.fullmatch(r"[A-Za-z0-9][A-Za-z0-9 _-]{0,31}", definitionName): errors.append("Workload Definition Name does not meet the public-schema pattern.")
if definitionVersion < 1: errors.append("Workload Definition Version must be at least 1.")
if len(definitionDescription) > 1024: errors.append("Description exceeds 1024 characters.")
if platform != "UnifiedEdge": errors.append("Platform Type must be UnifiedEdge.")
if preferredVersion and not waitRequested: errors.append("Wait for Validation must remain true when Preferred Version is true.")
if (waitRequested or preferredVersion) and not 30 <= timeoutSeconds <= 3600: errors.append("Wait Timeout Seconds must be from 30 through 3600.")
if not isinstance(configs, list) or not configs: errors.append("Blueprint Configuration must be a non-empty JSON array.")
normalized, localNames, catalogClauses = [], set(), []
if isinstance(configs, list):
    for index, item in enumerate(configs):
        if not isinstance(item, dict): errors.append("Blueprint Configuration entry %d must be an object." % index); continue
        allowed = {"Name","CatalogSelectorType","CatalogName","CatalogMoid","BlueprintName","VersionSelection","Version","Input","InputOverride","ResourceConstraint"}
        extra = set(item) - allowed
        if extra: errors.append("Blueprint Configuration entry %d contains unsupported fields: %s." % (index, ",".join(sorted(extra))))
        local = str(item.get("Name") or "").strip()
        selector = str(item.get("CatalogSelectorType") or "").strip()
        blueprint = str(item.get("BlueprintName") or "").strip()
        selection = str(item.get("VersionSelection") or "").strip()
        if not re.fullmatch(r"[A-Za-z0-9][A-Za-z0-9 _-]{0,31}", local): errors.append("Blueprint local Name at entry %d is invalid." % index)
        if local in localNames: errors.append("Blueprint local Name values must be unique: " + local)
        localNames.add(local)
        if selector not in ("Name","Moid"): errors.append("CatalogSelectorType at entry %d must be Name or Moid." % index)
        catalogName = str(item.get("CatalogName") or "").strip()
        catalogMoid = str(item.get("CatalogMoid") or "").strip()
        if selector == "Name" and not catalogName: errors.append("CatalogName is required at entry %d." % index)
        if selector == "Moid" and not re.fullmatch(r"[0-9A-Fa-f]{24}", catalogMoid): errors.append("CatalogMoid is invalid at entry %d." % index)
        if not re.fullmatch(r"[A-Za-z0-9][A-Za-z0-9_]{0,31}", blueprint): errors.append("BlueprintName is invalid at entry %d." % index)
        if selection not in ("Default","Specific"): errors.append("VersionSelection at entry %d must be Default or Specific." % index)
        try: requestedVersion = int(item.get("Version", 0))
        except Exception: requestedVersion = 0
        if selection == "Specific" and requestedVersion < 1: errors.append("Version must be at least 1 at entry %d." % index)
        inputValue = item.get("Input", {})
        overrides = item.get("InputOverride", [])
        constraint = item.get("ResourceConstraint")
        if not isinstance(inputValue, dict): errors.append("Input at entry %d must be an object." % index)
        if not isinstance(overrides, list) or any(not isinstance(value, str) for value in overrides): errors.append("InputOverride at entry %d must be a string array." % index)
        if constraint is not None and (not isinstance(constraint, dict) or set(constraint) - {"Input"} or not isinstance(constraint.get("Input", {}), dict)): errors.append("ResourceConstraint at entry %d must contain only an Input object." % index)
        normalized.append({"Name":local,"CatalogSelectorType":selector,"CatalogName":catalogName,"CatalogMoid":catalogMoid,"BlueprintName":blueprint,"VersionSelection":selection,"Version":requestedVersion,"Input":inputValue if isinstance(inputValue,dict) else {},"InputOverride":overrides if isinstance(overrides,list) else [],"ResourceConstraint":constraint})
        catalogClauses.append("Moid eq '%s'" % catalogMoid if selector == "Moid" else "Name eq '%s'" % catalogName.replace("'", "''"))
if not isinstance(parsedTags, list): errors.append("Tags must be a JSON array.")
else:
    tagKeys = set()
    for tag in parsedTags:
        if not isinstance(tag, dict) or set(tag) - {"Key","Value"} or not str(tag.get("Key") or ""): errors.append("Every tag must contain a non-empty Key and optional Value only."); continue
        if tag["Key"] in tagKeys: errors.append("Tag keys must be unique: " + tag["Key"])
        tagKeys.add(tag["Key"])
if parsedRollout is not None:
    if not preferredVersion: errors.append("Preferred Version Rollout Strategy is allowed only when Preferred Version is true.")
    if not isinstance(parsedRollout, dict): errors.append("Preferred Version Rollout Strategy must be an object.")
    else:
        kind = parsedRollout.get("ObjectType") or parsedRollout.get("ClassId")
        allowed = {"ClassId","ObjectType"} if kind == "workload.BatchDeployment" else {"ClassId","ObjectType","RolloutPercentages"}
        if kind not in ("workload.BatchDeployment","workload.CanaryDeployment"): errors.append("Rollout strategy type must be workload.BatchDeployment or workload.CanaryDeployment.")
        elif set(parsedRollout) - allowed: errors.append("Rollout strategy contains read-only or unsupported fields.")
        elif parsedRollout.get("ClassId", kind) != kind or parsedRollout.get("ObjectType", kind) != kind: errors.append("Rollout strategy ClassId and ObjectType must match.")
        elif kind == "workload.CanaryDeployment" and (not isinstance(parsedRollout.get("RolloutPercentages", []), list) or any(not isinstance(v,int) or isinstance(v,bool) or v < 1 or v > 100 for v in parsedRollout.get("RolloutPercentages", []))): errors.append("Canary RolloutPercentages must be integer percentages from 1 through 100.")
        parsedRollout = {"ClassId":kind,"ObjectType":kind, **({"RolloutPercentages":parsedRollout.get("RolloutPercentages", [])} if kind == "workload.CanaryDeployment" else {})}
status, statusCode = ("invalid", 400) if errors else ("ok", 200)
message = " ".join(errors) if errors else "Create request is valid."
resultJson = json.dumps({"error":message}, separators=(",", ":")) if errors else "{}"
ready = True
refName = definitionName.replace(" ","_").replace("-","_")
organizationUrl = "/api/v1/organization/Organizations?$filter=Name eq '%s'&$select=Moid,Name" % organization.replace("'", "''")
catalogUrl = "/api/v1/workflow/Catalogs?$filter=" + (" or ".join(sorted(set(catalogClauses))) if catalogClauses else "Moid eq '000000000000000000000000'") + "&$select=Moid,Name,Organization"
configJson = json.dumps(normalized, separators=(",", ":"), ensure_ascii=False)
tagsJson = json.dumps(parsedTags if isinstance(parsedTags,list) else [], separators=(",", ":"), ensure_ascii=False)
rolloutJson = json.dumps(parsedRollout, separators=(",", ":")) if parsedRollout is not None else ""

import json
import sys

def has_default(definition):
    default = definition.get("Default")
    return isinstance(default, dict) and "Value" in default

def validate_values(values, definitions, context):
    errors = []
    if not isinstance(values, dict):
        return [context + " must be a JSON object."]
    definitions = definitions or []
    if not isinstance(definitions, list):
        return [context + " definition is not an array."]
    for definition in definitions:
        if not isinstance(definition, dict):
            errors.append(context + " contains a malformed data-type definition.")
            continue
        name = definition.get("Name")
        if not name:
            errors.append(context + " contains an unnamed data-type definition.")
            continue
        if definition.get("Required") is True and name not in values and not has_default(definition):
            errors.append(context + " is missing required value " + name + ".")
            continue
        if name not in values:
            continue
        value = values[name]
        objectType = definition.get("ObjectType") or definition.get("ClassId")
        if objectType == "workflow.PrimitiveDataType":
            properties = definition.get("Properties") or {}
            kind = properties.get("Type", "string")
            valid = ((kind in ("string", "enum") and isinstance(value, str)) or
                     (kind == "integer" and isinstance(value, int) and not isinstance(value, bool)) or
                     (kind == "float" and isinstance(value, (int, float)) and not isinstance(value, bool)) or
                     (kind == "boolean" and isinstance(value, bool)) or kind == "json")
            if not valid:
                errors.append(context + "." + name + " does not match primitive type " + kind + ".")
                continue
            constraints = properties.get("Constraints") or {}
            minimum, maximum = constraints.get("Min"), constraints.get("Max")
            measured = len(value) if isinstance(value, str) else value
            if minimum not in (None, 0) and measured < minimum:
                errors.append(context + "." + name + " is below its minimum constraint.")
            if maximum not in (None, 0) and measured > maximum:
                errors.append(context + "." + name + " exceeds its maximum constraint.")
            enumList = constraints.get("EnumList") or []
            if kind == "enum" and enumList:
                allowed = [entry.get("Value") for entry in enumList if isinstance(entry, dict)]
                if value not in allowed:
                    errors.append(context + "." + name + " is not in the blueprint enum.")
        elif objectType == "workflow.ArrayDataType":
            if not isinstance(value, list):
                errors.append(context + "." + name + " must be an array.")
            elif definition.get("Min") is not None and len(value) < int(definition["Min"]):
                errors.append(context + "." + name + " has too few items.")
            elif definition.get("Max") is not None and len(value) > int(definition["Max"]):
                errors.append(context + "." + name + " has too many items.")
        elif objectType in ("workflow.CustomDataType", "workflow.DynamicTemplateParserDataType"):
            errors.append(context + "." + name + " uses a custom data type whose complete constraint schema is not present on the blueprint response; live-tenant validation is required and the workflow fails closed.")
        elif objectType and objectType.startswith("workflow.MoReference"):
            if not isinstance(value, dict):
                errors.append(context + "." + name + " must be a managed-object reference object.")
    return errors

def strip_reference(config, blueprint):
    reference = {
        "ClassId": "workload.BlueprintReference",
        "ObjectType": "workload.BlueprintReference",
        "Name": config["Name"],
        "Blueprint": {"ClassId": "mo.MoRef", "ObjectType": "workload.Blueprint", "Moid": blueprint["Moid"]},
        "Input": config.get("Input") or {},
        "InputOverride": config.get("InputOverride") or [],
    }
    constraint = config.get("ResourceConstraint")
    if isinstance(constraint, dict):
        reference["ResourceConstraint"] = {"ClassId": "workload.ResourceConstraint", "ObjectType": "workload.ResourceConstraint", "Input": constraint.get("Input") or {}}
    return reference

body = json.loads(sys.argv[1])
configs = json.loads(sys.argv[2])
organizationMoid, definitionName = sys.argv[3], sys.argv[4]
definitionVersion, definitionDescription = int(sys.argv[5]), sys.argv[6]
tags = json.loads(sys.argv[7])
preferred = sys.argv[8].strip().lower() == "true"
rollout = json.loads(sys.argv[9]) if sys.argv[9].strip() else None
status, statusCode, message, resultJson, ready = "ok", 200, "Definition request built", "{}", False
requestJson = collisionUrl = ""
try:
    rows = body.get("Results") if isinstance(body, dict) else None
    if not isinstance(rows, list): raise ValueError("Blueprint response has no Results array.")
    references, usedMoids, errors = [], set(), []
    for config in configs:
        matches = []
        for row in rows:
            catalog = row.get("Catalog") if isinstance(row,dict) else None
            versionMatch = row.get("DefaultVersion") is True if config["VersionSelection"] == "Default" else int(row.get("Version",0)) == config["Version"]
            if isinstance(catalog,dict) and catalog.get("Moid") == config["ResolvedCatalogMoid"] and row.get("Name") == config["BlueprintName"] and versionMatch:
                matches.append(row)
        if len(matches) != 1:
            errors.append("Blueprint selector %s resolved %d results." % (config["Name"], len(matches))); continue
        blueprint = matches[0]
        if blueprint.get("Moid") in usedMoids: errors.append("The same concrete blueprint version is referenced more than once."); continue
        usedMoids.add(blueprint.get("Moid"))
        validation = blueprint.get("ValidationInformation") or {}
        if validation.get("EngineState") != "Updated" or validation.get("State") != "Valid": errors.append("Blueprint %s is not Updated and Valid." % config["Name"]); continue
        errors += validate_values(config.get("Input") or {}, blueprint.get("InputDefinition") or [], "Blueprint input " + config["Name"])
        resourceDefinition = blueprint.get("ResourceDefinition") or {}
        constraintInput = (config.get("ResourceConstraint") or {}).get("Input", {})
        errors += validate_values(constraintInput, resourceDefinition.get("InputDefinition") or [], "Resource constraint " + config["Name"])
        references.append(strip_reference(config, blueprint))
    if errors:
        status, statusCode, message = "invalid", 422, " ".join(errors)
        resultJson = json.dumps({"error":message,"liveTenantCaveat":"Custom blueprint data types fail closed because their referenced definitions are not embedded in the blueprint response."}, separators=(",", ":"))
    else:
        payload = {"ClassId":"workload.WorkloadDefinition","ObjectType":"workload.WorkloadDefinition","Name":definitionName,"Version":definitionVersion,"Description":definitionDescription,"PlatformType":["UnifiedEdge"],"Blueprints":references,"PreferredVersion":preferred,"Organization":{"ClassId":"mo.MoRef","ObjectType":"organization.Organization","Moid":organizationMoid},"Tags":tags}
        if rollout is not None: payload["PreferredVersionRolloutStrategy"] = rollout
        requestJson = json.dumps(payload, separators=(",", ":"), ensure_ascii=False)
        escapedName, escapedRef = definitionName.replace("'","''"), definitionName.replace(" ","_").replace("-","_").replace("'","''")
        collisionUrl = "/api/v1/workload/WorkloadDefinitions?$filter=Organization.Moid eq '%s' and (Name eq '%s' or RefName eq '%s')&$select=Moid,Name,Version,RefName&$top=1" % (organizationMoid, escapedName, escapedRef)
        resultJson = json.dumps({"resolvedBlueprintCount":len(references),"request":payload}, separators=(",", ":"), ensure_ascii=False)
    ready = True
except Exception as exc:
    status, statusCode, message = "malformed", 502, str(exc)
    resultJson, ready = json.dumps({"error":message}, separators=(",", ":")), True

import json
import sys

status, statusCode, message, resultJson, ready = "ok", 200, "Validation state inspected", "{}", False
pollState = "pending"
finalResultJson = "{}"
try:
    body = json.loads(sys.argv[1])
    expectedMoid, expectedName, expectedVersion = sys.argv[2], sys.argv[3], int(sys.argv[4])
    if not isinstance(body, dict) or body.get("Moid") != expectedMoid or body.get("Name") != expectedName or int(body.get("Version", 0)) != expectedVersion:
        status, statusCode, message = "identity-mismatch", 409, "Polled definition identity changed."
    else:
        validation = body.get("ValidationInformation") or {}
        engineState, state = validation.get("EngineState"), validation.get("State")
        if engineState == "Updated" and state == "Valid":
            pollState, message = "success", "Definition validation completed successfully."
        elif engineState == "UpdateFailed" or state == "Invalid":
            pollState, message = "failure", "Definition validation failed."
        elif engineState in ("NotUpdated", "Updating", "Updated") and state in ("NotValidated", "Valid"):
            pollState, message = "pending", "Definition validation remains in progress."
        else:
            status, statusCode, message = "unexpected-state", 502, "Definition returned an undocumented validation-state combination."
        finalResultJson = json.dumps(body, separators=(",", ":"), ensure_ascii=False)
        resultJson = finalResultJson if status == "ok" else json.dumps({"error": message, "definition": body}, separators=(",", ":"))
    ready = True
except Exception as exc:
    status, statusCode, message = "malformed", 502, str(exc)
    resultJson, ready = json.dumps({"error": message}, separators=(",", ":")), True
